package com.clavis.reader;
import android.app.job.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import androidx.swiperefreshlayout.widget.SwipeRefreshLayout;import java.util.*;import java.util.concurrent.*;
/** Shared, bounded refresh work; the UI remains usable while publishers update. */
final class FeedRefresh {
 static final ExecutorService coordinator=Executors.newSingleThreadExecutor(),downloads=Executors.newFixedThreadPool(6);
 static final Handler main=new Handler(Looper.getMainLooper());static final WeakHashMap<MainActivity,Boolean> observers=new WeakHashMap<>();static final HashMap<String,ArrayList<Runnable>> running=new HashMap<>();
 static void observe(MainActivity a){observers.put(a,true);}static void forget(MainActivity a){observers.remove(a);}
 static void schedule(Context c){JobScheduler scheduler=c.getSystemService(JobScheduler.class);if(scheduler==null)return;ComponentName service=new ComponentName(c,FeedRefreshJob.class);scheduler.schedule(new JobInfo.Builder(7131,service).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY).setRequiresBatteryNotLow(true).setPersisted(true).setPeriodic(2*60*60*1000L).build());}
 static void maybe(Context c,String kind){if(kind.equals("Podcasts"))return;long last=c.getSharedPreferences("feed_refresh",0).getLong("attempt_"+kind,0);if(System.currentTimeMillis()-last>30*60*1000L)request(c,kind,null,null);}
 static void request(Context context,String kind,List<FeedStore.Feed> only,Runnable done){Context app=context.getApplicationContext();String key=only==null?kind:kind+":"+only.stream().map(f->f.url).sorted().collect(java.util.stream.Collectors.joining("|"));synchronized(running){ArrayList<Runnable> existing=running.get(key);if(existing!=null){if(done!=null)existing.add(done);return;}ArrayList<Runnable> callbacks=new ArrayList<>();if(done!=null)callbacks.add(done);running.put(key,callbacks);}app.getSharedPreferences("feed_refresh",0).edit().putLong("attempt_"+kind,System.currentTimeMillis()).apply();
  coordinator.execute(()->{List<FeedStore.Feed> source=only==null?FeedStore.load(app):only;ArrayList<Future<FeedStore.Feed>> work=new ArrayList<>();for(FeedStore.Feed old:source)if(old.kind.equals(kind))work.add(downloads.submit(()->{try{FeedStore.Feed fresh=FeedStore.download(old.url,old.kind);fresh.title=old.title;if(fresh.items.isEmpty()&&!old.items.isEmpty()){fresh.items=old.items;fresh.error="Publisher returned no entries; showing saved stories";}if(fresh.image.isEmpty())fresh.image=old.image;FeedCatalog.applyPolicy(app,fresh);return fresh;}catch(Exception error){old.error=error.getMessage()==null?"Could not refresh":error.getMessage();return old;}}));HashMap<String,FeedStore.Feed> updates=new HashMap<>();int successful=0;for(Future<FeedStore.Feed> future:work)try{FeedStore.Feed feed=future.get();updates.put(feed.url,feed);if(feed.error.isEmpty())successful++;}catch(Exception ignored){}
   synchronized(FeedStore.class){ArrayList<FeedStore.Feed> current=FeedStore.load(app);for(int n=0;n<current.size();n++){FeedStore.Feed old=current.get(n);if(old.kind.equals(kind)&&updates.containsKey(old.url))current.set(n,updates.get(old.url));}FeedStore.save(app,current);}boolean changed=successful>0;if(changed){FeedTopics.prefs(app).edit().putBoolean("latest_"+kind,true).apply();app.getSharedPreferences("feed_refresh",0).edit().putLong("updated_"+kind,System.currentTimeMillis()).apply();}
   main.post(()->{ArrayList<Runnable> callbacks;synchronized(running){callbacks=running.remove(key);}if(callbacks!=null)for(Runnable callback:callbacks)callback.run();if(changed)for(MainActivity a:new ArrayList<>(observers.keySet()))if(a!=null&&!a.isFinishing()&&!a.isDestroyed()){if(a.screen.equals(kind))FeedScreens.show(a,kind,a.feedSources);else if(a.screen.equals(kind+" feed")&&a.openFeed!=null)FeedScreens.items(a,a.openFeed);}});
  });
 }
 static void manual(MainActivity a,String kind,List<FeedStore.Feed> feeds){if(feeds.isEmpty()){FeedScreens.add(a,kind);return;}AppNotice.makeText(a,"Refreshing in background…",Toast.LENGTH_SHORT).show();int count=0;for(FeedStore.Feed source:FeedStore.load(a))if(source.kind.equals(kind))count++;request(a,kind,feeds.size()==count?null:feeds,()->{if(a.isDestroyed()||a.isFinishing())return;boolean failed=false;for(FeedStore.Feed source:FeedStore.load(a))if(source.kind.equals(kind)&&!source.error.isEmpty())failed=true;AppNotice.makeText(a,failed?"Some sources could not refresh. Saved stories are still available.":"Feeds updated",Toast.LENGTH_SHORT).show();});}
 static View wrap(MainActivity a,View content,String kind,FeedStore.Feed source){if(kind.equals("Podcasts"))return content;SwipeRefreshLayout swipe=new SwipeRefreshLayout(a){float startX,startY;boolean sideways;@Override public boolean onInterceptTouchEvent(android.view.MotionEvent event){if(event.getActionMasked()==android.view.MotionEvent.ACTION_DOWN){startX=event.getX();startY=event.getY();sideways=false;}if(event.getActionMasked()==android.view.MotionEvent.ACTION_MOVE&&Math.abs(event.getX()-startX)>android.view.ViewConfiguration.get(a).getScaledTouchSlop()&&Math.abs(event.getX()-startX)>Math.abs(event.getY()-startY))sideways=true;return !sideways&&super.onInterceptTouchEvent(event);}};swipe.setContentDescription("Pull to refresh "+FeedCatalog.label(kind).toLowerCase(Locale.ROOT));swipe.setColorSchemeColors(AppTheme.accent);swipe.setProgressBackgroundColorSchemeColor(AppTheme.surface);swipe.addView(content,new android.view.ViewGroup.LayoutParams(-1,-1));swipe.setOnChildScrollUpCallback((parent,child)->content.canScrollVertically(-1));swipe.setOnRefreshListener(()->request(a,kind,source==null?null:Collections.singletonList(source),()->swipe.setRefreshing(false)));return swipe;}
 static void pull(MainActivity a,View content,String kind,FeedStore.Feed source){if(kind.equals("Podcasts")||!(content.getParent() instanceof android.view.ViewGroup))return;android.view.ViewGroup host=(android.view.ViewGroup)content.getParent();if(host instanceof SwipeRefreshLayout)return;int index=host.indexOfChild(content);android.view.ViewGroup.LayoutParams params=content.getLayoutParams();host.removeView(content);host.addView(wrap(a,content,kind,source),index,params);}
 static void pullSources(MainActivity a,String kind){for(int n=0;n<a.root.getChildCount();n++)if(a.root.getChildAt(n) instanceof ScrollView){pull(a,a.root.getChildAt(n),kind,null);break;}}
}
